fn prime_num(n: u64) -> bool {
    // Assumption: n >= 2
    if n == 2 || n == 3 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }

    // Check odd divisors up to sqrt(n) using i <= n / i to avoid overflow.
    let mut i: u64 = 3;
    while i <= n / i {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}